```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
)

type StructParserOptions struct {
	Filepath string
}

func (opts *StructParserOptions) Parse() (*struct{}, error) {
	file, err := os.Open(opts.Filepath)
	if err != nil {
		return nil, fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	data, err := ioutil.ReadAll(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	var tree ast.ExprStmt
	err = parser.ParseExpr(data, &tree, token.NewFileSet())
	if err != nil {
		return nil, fmt.Errorf("error parsing AST: %w", err)
	}

	structType, ok := tree.X.(*ast.TypeSpec)
	if !ok {
		return nil, fmt.Errorf("expected TypeSpec but got %T", tree.X)
	}

	return structType, nil
}

func main() {
	var opts StructParserOptions
	args := os.Args[1:]

	if len(args) < 2 {
		fmt.Println("Usage: go run script.go filepath structname")
		os.Exit(1)
	}

	opts.Filepath = args[0]
	structName := args[1]

	structType, err := opts.Parse()
	if err != nil {
		log.Fatalf("Error parsing struct: %v", err)
	}

	// Generate the Avro schema based on the struct type.
	schema, err := json.MarshalIndent(structType, "", "    ")
	if err != nil {
		log.Fatalf("Error marshaling JSON: %v", err)
	}

	// Write the schema to a file.
	outFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		log.Fatalf("Error creating file: %v", err)
	}
	defer outFile.Close()

	_, err = outFile.Write(schema)
	if err != nil {
		log.Fatalf("Error writing schema to file: %v", err)
	}

	fmt.Printf("Generated Avro schema for %s.avsc\n", structName)
}
```

### How to Use This Program:

1. **Compile the Program**: Save this code as `main.go`. Then compile it using `go build -o struct_avro_gen`.

2. **Run the Program**: Execute the compiled binary along with the path to your Go source file and the struct name you want to convert. For example:
   ```sh
   ./struct_avro_gen /path/to/your/file.go my_struct
   ```

3. **Result File**: The program will create a file named `my_struct.avsc` containing the Avro schema for the specified struct.

### Example Usage:

- Suppose your Go source file (`example.go`) has the following structure:
